import java.util.*;

class FrequencyAnalyzer {
    private FrequencyAnalyzer() {}

    static Map<Character, Integer> countChars(String input) {
        Map<Character, Integer> freq = new LinkedHashMap<>();
        for (char c : input.toCharArray()) {
            freq.merge(c, 1, Integer::sum);
        }
        return freq;
